solutionCode:
import { useState } from 'react';

const INITIAL_VISITORS = [
  { id: 1, name: 'Alice Johnson', company: 'Acme Corp', status: 'Not Arrived' as const },
  { id: 2, name: 'Bob Smith', company: 'Globex Inc', status: 'Checked In' as const },
  { id: 3, name: 'Carol Lee', company: 'Initech', status: 'Not Arrived' as const }
];

type VisitorStatus = 'Not Arrived' | 'Checked In' | 'Checked Out';
type Visitor = { id: number; name: string; company: string; status: VisitorStatus };

type FilterOption = 'All' | 'Checked In' | 'Not Arrived';

export default function VisitorCheckIn() {
  const [visitors, setVisitors] = useState<Visitor[]>(INITIAL_VISITORS);
  const [filter, setFilter] = useState<FilterOption>('All');

  const updateStatus = (id: number, status: VisitorStatus) => {
    setVisitors((prev) =>
      prev.map((visitor) =>
        visitor.id === id ? { ...visitor, status } : visitor
      )
    );
  };

  const filteredVisitors = visitors.filter((visitor) => {
    if (filter === 'All') return true;
    if (filter === 'Checked In') return visitor.status === 'Checked In';
    if (filter === 'Not Arrived') return visitor.status === 'Not Arrived';
    return true;
  });

  return (
    <div style={{ padding: '1.5rem' }}>
      <h2>Visitor Check-In</h2>
      <div style={{ marginBottom: '1rem' }}>
        <button onClick={() => setFilter('All')}>All</button>{' '}
        <button onClick={() => setFilter('Checked In')}>Checked In</button>{' '}
        <button onClick={() => setFilter('Not Arrived')}>Not Arrived</button>
      </div>
      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr>
            <th style={{ textAlign: 'left', borderBottom: '1px solid #ccc' }}>Name</th>
            <th style={{ textAlign: 'left', borderBottom: '1px solid #ccc' }}>Company</th>
            <th style={{ textAlign: 'left', borderBottom: '1px solid #ccc' }}>Status</th>
            <th style={{ textAlign: 'left', borderBottom: '1px solid #ccc' }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {filteredVisitors.map((visitor) => (
            <tr key={visitor.id}>
              <td>{visitor.name}</td>
              <td>{visitor.company}</td>
              <td>{visitor.status}</td>
              <td>
                {visitor.status !== 'Checked In' && (
                  <button onClick={() => updateStatus(visitor.id, 'Checked In')}>
                    Check In
                  </button>
                )}
                {visitor.status === 'Checked In' && (
                  <button onClick={() => updateStatus(visitor.id, 'Checked Out')}>
                    Check Out
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
